354		if _, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}); err != nil {
355			t.Fatal(err)
356		}
357		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
358			{Time: 400, DX: 1, Observations: []Observation{{ID: "L"}}},
359		}}); err != nil {
360			t.Fatal(err)
361		}
362		if _, err := m.Correct(Correction{ID: "c2", Anchor: 100, Target: CorrectionTarget{X: 7, Y: 8, Variance: 2}}); err != nil {
363			t.Fatal(err)
364		}
365		if err := m.Close(); err != nil {
366			t.Fatal(err)
367		}
368	
369		fd := readFileData(t, path)
370		if b, a := findCorrCount(t, &fd, 0, "L", 1); b != 3 || a != 3 {
371			t.Fatalf("c1 counts = %d/%d, want 3/3", b, a)
372		}
373		if b, a := findCorrCount(t, &fd, 1, "L", 1); b != 4 || a != 4 {
374			t.Fatalf("c2 counts = %d/%d, want 4/4", b, a)
375		}
376		m2, err := Open(path)
377		if err != nil {
378			t.Fatalf("open both records: %v", err)
379		}
380		m2.Close()
381	
382		// c1 提前结束，不能写成 c2 时的 4。
383		tamperFile(t, path, func(fd *fileData) { setCorrCount(fd, 0, "L", 1, 4, 4) })
384		assertOpenCorrupt(t, path)
385	}
386	
387	// 校正范围内含缺失逐帧来源的 null 旧帧时，保留现有打开规则、不推测缺失
388	// 观测：即使手写记录的次数明显与可见来源不符也不按次数核对拒绝。同一文
389	// 件中另一条依据完整的记录被改坏次数时仍须拒绝。
390	func TestOpenSkipsCountCheckWhenRangeLacksBasis(t *testing.T) {
391		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
392		path := filepath.Join(t.TempDir(), "m.pose")
393		m, err := Create(path, cfg)
394		if err != nil {
395			t.Fatal(err)
396		}
397		if _, err := m.ImportSegment(Segment{ID: "old", Frames: []Frame{
398			{Time: 100, DX: 1, Observations: []Observation{{ID: "K"}}},
399			{Time: 200, DX: 1, Observations: []Observation{{ID: "K"}}},
400		}}); err != nil {
401			t.Fatal(err)
402		}
403		writeLegacyV1File(t, path, m.state)
404		m.Close()
405	
406		m2, err := Open(path)
407		if err != nil {
408			t.Fatal(err)
409		}
