412		}}); err != nil {
413			t.Fatal(err)
414		}
415		cur, _ := m2.PoseAt(300)
416		if _, err := m2.Correct(Correction{ID: "cfull", Anchor: 300, Target: CorrectionTarget{
417			X: cur.X, Y: cur.Y, Heading: cur.Heading, Variance: cur.Variance,
418		}}); err != nil {
419			t.Fatal(err)
420		}
421		if err := m2.Close(); err != nil {
422			t.Fatal(err)
423		}
424	
425		// 手写一条覆盖 t=100..300（含 null 旧帧）的记录，故意把 K/1 次数写
426		// 成与任何口径都不符的 99：依据不完整，保留旧规则照常打开。
427		tamperFile(t, path, func(fd *fileData) {
428			cr := corrRecJSON{ID: "span", Anchor: 100, EndTime: 300,
429				Target: CorrectionTarget{X: 5, Y: 6, Variance: 1}}
430			for j := 1; j < len(fd.Trajectory); j++ {
431				cr.Poses = append(cr.Poses, poseChangeJSON{Before: fd.Trajectory[j], After: fd.Trajectory[j]})
432			}
433			cr.Landmarks = []landmarkChangeJSON{{
434				ID: "K", Occurrence: 1,
435				Before: Landmark{ID: "K", X: 1, Y: 1, Count: 99},
436				After:  Landmark{ID: "K", X: 1, Y: 1, Count: 99},
437			}}
438			fd.Corrections = append(fd.Corrections, cr)
439		})
440		m3, err := Open(path)
441		if err != nil {
