451		// 同一文件中依据完整的 cfull 记录改坏次数：仍须拒绝整份地图。
452		tamperFile(t, path, func(fd *fileData) { setCorrCount(fd, 0, "K", 1, 7, 7) })
453		assertOpenCorrupt(t, path)
454	}
455	
456	// 次数矛盾的错误必须可 errors.Is 识别为 ErrCorrupt，且错误信息指出校正
457	// 标识、路标标识与出现编号。
458	func TestOpenCorrectionCountErrorIdentifiesRecordLandmarkOccurrence(t *testing.T) {
459		path := filepath.Join(t.TempDir(), "m.pose")
