485		var (
486			replay      *observationReplay
487			tally       *sourceObservationTally
488			legacyByKey map[occurrenceKey]int
489		)
490		// endSrcIdxs 预登记各校正记录结束帧对应的来源下标 k（对应帧
491		// trajectory[k+1]），只让共享扫描为这些下标保留“截至该帧”的累计快
492		// 照，避免对每一帧都复制整份计数。
493		endSrcIdxs := make(map[int]struct{})
494		if len(fd.Sources) != 0 {
495			replay = newObservationReplay(fd.Config.MergeDistance)
496			for _, lm := range fd.Landmarks {
497				replay.track(lm.ID, occurrenceWindowsOf(lm))
498			}
499			for _, cr := range fd.Corrections {
500				for j := 1; j < len(fd.Trajectory); j++ {
501					if fd.Trajectory[j].Time == cr.EndTime {
502						endSrcIdxs[j-1] = struct{}{}
503						break
504					}
505				}
506			}
507		}
508		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
509		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
510		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
511		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
512		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
513		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
514		if len(fd.Sources) != 0 {
515			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
516			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
517			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
518			// 也不能按帧数猜测。同时记录归属各次出现的最早来源观测帧时间，
519			// 供下方首次观测时间核对使用。
520			tallies := make(map[string]map[int]int, len(fd.Landmarks))
521			firstObs := make(map[string]map[int]int64, len(fd.Landmarks))
522			for k, src := range fd.Sources {
523				if src == nil {
524					continue // 旧地图帧：无逐帧依据，不要求补齐归属
525				}
526				t := fd.Trajectory[k+1].Time
527				for _, ob := range src.Observations {
528					num, known := replay.occurrenceOf(ob.ID, t)
529					if !known {
530						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
531					}
532					if num == 0 {
533						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
534					}
535					c := tallies[ob.ID]
536					if c == nil {
537						c = make(map[int]int, 1)
538						tallies[ob.ID] = c
539					}
540					c[num]++
541					f := firstObs[ob.ID]
542					if f == nil {
543						f = make(map[int]int64, 1)
544						firstObs[ob.ID] = f
545					}
546					if cur, ok := f[num]; !ok || t < cur {
547						f[num] = t
548					}
549				}
550			}
551			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
552			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
553			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
554			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
555			// 次数，正常校正后保存的文件仍满足此不变量。
556			for _, lm := range fd.Landmarks {
557				if len(lm.Occurrences) == 0 {
558					// 旧版平铺路标即第 1 次出现。
559					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
560						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
561					}
562					continue
563				}
564				for _, oj := range lm.Occurrences {
565					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
566						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
567					}
568				}
569			}
570	
571			// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
572			// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
573			// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
574			// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
575			// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
576			// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
577			// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
578			// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
579			// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
580			// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
581			// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
582			// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
583			// 确保存的校正地图仍满足此不变量。
584			for _, lm := range fd.Landmarks {
585				for _, oj := range lm.Occurrences {
586					if !oj.HasFirstSeen || oj.LegacyCount > 0 {
587						continue
588					}
589					// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
590					// 帧时间必然已记录；缺失本身即矛盾。
591					first, ok := firstObs[lm.ID][oj.Number]
592					if !ok || first != oj.FirstSeenTime {
593						return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
594					}
595				}
596			}
597	
598			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
599			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
600			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
601			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
602			// 空观测帧不增加贡献。归组、固定旧贡献起点与逐条重建全部经由与
603			// 回环校正共享的重放器（见 replay.go，单条接纳规则见 aggregate.go），
604			// 旧文件固定旧贡献（LegacyCount 次平均）作为聚合起点——不能当成零，
605			// 也不能用缺少依据的帧数代替。回环校正后保存的文件按当前轨迹重放
606			// 即得到当前位置，不要求等于校正记录里的历史快照；各次出现分别核
